import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for element‑wise multiplication (diag(A) * B)
# ----------------------------------------------------------------------
mul_kernel_source = """
__global__ void mul_kernel(int N, int M, const float* diag_a, const float* B, float* out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * M) {
        int i = idx / M;          // row index
        int j = idx % M;          // column index
        out[idx] = diag_a[i] * B[idx];
    }
}
"""

# ----------------------------------------------------------------------
# Custom CUDA function that launches the kernel and returns the result tensor
# ----------------------------------------------------------------------
mul_cuda_source = """
torch::Tensor mul_cuda(torch::Tensor a, torch::Tensor b) {
    auto N = a.size();          // A is 1‑D of length N
    auto M = b.shape[1];        // B has shape (N, M)
    auto out = torch.zeros(N, M);

    const int block_size = 256;
    const int num_blocks = (N * M + block_size - 1) / block_size;

    mul_kernel<<<num_blocks, block_size>>>(N, M, a.data_ptr<float>(), b.data_ptr<float()>, out.data_ptr<float>());

    return out;
}
"""

# ----------------------------------------------------------------------
# Separate C++ function signature (needed by load_inline)
# ----------------------------------------------------------------------
elementmul_cpp_source = "torch::Tensor mul_cuda(torch::Tensor a, torch::Tensor b);"

# ----------------------------------------------------------------------
# Load the custom CUDA operator into memory
# ----------------------------------------------------------------------
elementwise_mul = load_inline(
    name="elementwise_mul",
    cpp_sources=elementmul_cpp_source,
    cuda_sources=mul_kernel_source,   # kernel definition (CUDA source)
    functions=["mul_cuda"],
    verbose=True,
)

# ----------------------------------------------------------------------
# Optimized model that replaces the original forward with the custom operator
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_mul = elementwise_mul

    def forward(self, A, B):
        """
        Args:
            A (torch.Tensor): 1‑D tensor of shape (N,) – diagonal entries.
            B (torch.Tensor): 2‑D tensor of shape (N, M).
        Returns:
            torch.Tensor: Result of diag(A) @ B, i.e. A[:, None] * B, shape (N, M).
        """
        return self.elementwise_mul(A, B)
